if (!$json.notification_id || !$json.lease_token || !$json.payload) throw new Error('Invalid claimed email job');
if ($json.channel !== 'email') throw new Error('Unexpected notification channel');
const p = $json.payload;
if (p.contract_version !== 'notification-v1') throw new Error('Unsupported notification contract');
const scalar = (value,max=240) => String(value ?? 'Non renseigné').replace(/[\u0000-\u001f\u007f]+/g,' ').replace(/\s+/g,' ').trim().slice(0,max) || 'Non renseigné';
const escapeHtml = value => scalar(value,1000).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const facts = (p.analysis.observed_facts ?? []).slice(0,5).map(item => `- ${scalar(item.statement_fr)}`);
const uncertainties = (p.analysis.uncertainties ?? []).slice(0,5).map(item => `- ${scalar(item,200)}`);
const sources = (p.sources ?? []).slice(0,10).map(item => `- ${scalar(item.name)} — découverte : ${scalar(item.discovered_at)}`);
const email_subject = scalar(`[TCM][${p.claim.verification_status}] ${p.organization.name} — ${p.claim.threat_actor ?? 'acteur inconnu'}`,160);
const email_text = [`Alerte Threat Claim Monitor`, ``, `Identifiant : ${scalar(p.alert_id)}`, `Organisation : ${scalar(p.organization.name)}`, `Victime déclarée : ${scalar(p.claim.victim_name)}`, `Acteur : ${scalar(p.claim.threat_actor)}`, `Première observation : ${scalar(p.claim.first_seen_at)}`, `Dernière observation : ${scalar(p.claim.last_seen_at)}`, `Vérification : ${scalar(p.claim.verification_status)}`, `Correspondance : ${scalar(p.match.method)} (${Number(p.match.confidence_score)} / 100)`, `Analyse : ${scalar(p.analysis.summary_fr,600)}`, ``, `Faits observés :`, ...(facts.length?facts:['- Aucun fait structuré']), ``, `Incertitudes :`, ...(uncertainties.length?uncertainties:['- Aucune incertitude structurée']), ``, `Sources :`, ...sources, ``, scalar(p.disclaimer,300), ``, `Alert ID : ${scalar(p.alert_id)}`].join('\n').slice(0,6000);
const list = values => values.length ? `<ul>${values.map(value => `<li>${escapeHtml(value.replace(/^- /,''))}</li>`).join('')}</ul>` : '<p>Aucune valeur structurée</p>';
const email_html = `<h1>Alerte Threat Claim Monitor</h1><dl><dt>Identifiant</dt><dd>${escapeHtml(p.alert_id)}</dd><dt>Organisation</dt><dd>${escapeHtml(p.organization.name)}</dd><dt>Victime déclarée</dt><dd>${escapeHtml(p.claim.victim_name)}</dd><dt>Acteur</dt><dd>${escapeHtml(p.claim.threat_actor)}</dd><dt>Première observation</dt><dd>${escapeHtml(p.claim.first_seen_at)}</dd><dt>Dernière observation</dt><dd>${escapeHtml(p.claim.last_seen_at)}</dd><dt>Vérification</dt><dd>${escapeHtml(p.claim.verification_status)}</dd><dt>Correspondance</dt><dd>${escapeHtml(p.match.method)} (${Number(p.match.confidence_score)} / 100)</dd></dl><h2>Analyse</h2><p>${escapeHtml(scalar(p.analysis.summary_fr,600))}</p><h2>Faits observés</h2>${list(facts)}<h2>Incertitudes</h2>${list(uncertainties)}<h2>Sources</h2>${list(sources)}<hr><p><strong>${escapeHtml(scalar(p.disclaimer,300))}</strong></p><p>Alert ID : ${escapeHtml(p.alert_id)}</p>`.slice(0,10000);
return {json:{dispatch_context:{notification_id:$json.notification_id,lease_token:$json.lease_token},email_subject,email_text,email_html}};

const source = $('Render safe email').item.json.dispatch_context;
const detail = JSON.stringify($json.error ?? $json).toLowerCase();
let error_code = 'connection_failed';
if (detail.includes('credential') || detail.includes('authentication') || detail.includes('auth')) error_code = 'credential_unavailable';
else if (detail.includes('timeout') || detail.includes('timed out')) error_code = 'timeout';
else if (detail.includes('recipient') || detail.includes('envelope') || detail.includes('rejected')) error_code = 'delivery_rejected';
return {json:{delivery_result:{notification_id:source.notification_id,lease_token:source.lease_token,succeeded:false,response_status:null,response_excerpt:null,error_code}}};
